import logging

from app import db

log = logging.getLogger(__name__)


def get_connection():
    return db.connect()


def get_user_by_id(user_id: int):
    conn = get_connection()
    return conn.execute("SELECT * FROM users WHERE id = %s", (user_id,)).fetchone()


